#!/usr/bin/env bash
# scripts/_check_coverage.sh
# Fails CI if coverage is below 50%

set -euo pipefail

PACKAGE="${1:-apiserver}"
MIN_COVERAGE=50.0

echo "Checking coverage for $PACKAGE..."

# Run test.sh coverage
./test.sh "$PACKAGE" --coverage > tarpaulin_output.log 2>&1

# Parse coverage from .test_logs/coverage.json generated by llvm-cov
if [ ! -f ".test_logs/coverage.json" ]; then
    echo "Coverage file not found. Ensure test.sh --coverage succeeded."
    exit 1
fi

COVERAGE=$(python3 -c "
import json, sys
try:
    with open('.test_logs/coverage.json') as f:
        data = json.load(f)
    lines = data['data'][0]['summary']['lines']
    pct = (lines['covered'] / lines['count']) * 100
    print(f'{pct:.2f}')
except Exception as e:
    sys.exit(1)
")

if [ -z "$COVERAGE" ]; then
    echo "Failed to parse coverage."
    exit 1
fi

echo "Current coverage: $COVERAGE%"

if (( $(echo "$COVERAGE < $MIN_COVERAGE" | bc -l) )); then
    echo "Coverage ($COVERAGE%) is below minimum threshold ($MIN_COVERAGE%). Failing CI."
    exit 1
else
    echo "Coverage check passed."
    exit 0
fi
